export type FormFieldProps = InputHTMLAttributes<HTMLInputElement> & {
  label: string;
  hint?: string;
  error?: string;
};

export type DatePickerProps = Omit<FormFieldProps, "type" | "value" | "defaultValue" | "onChange"> & {
  /** ISO calendar date (YYYY-MM-DD), without timezone conversion. */
  value: string;
  onChange: (value: string) => void;
};

export type SearchableSelectProps = {
  label: string; options: SelectOption[]; value: string; onChange: (value: string) => void;
  id?: string; name?: string; placeholder?: string; disabled?: boolean; required?: boolean; error?: string;
};

export type RecordField<T> = {
  key: Extract<keyof T, string>;
  label: string;
  type?: "text" | "email" | "tel" | "number" | "date" | "time" | "select";
  required?: boolean;
  hint?: string;
  options?: SelectOption[];
  min?: number | string;
  max?: number | string;
  step?: number | "any";
  maxLength?: number;
  /** Optional display formatting for RecordDetail. */
  format?: (record: T) => ReactNode;
};

export type RecordFormProps<T> = {
  initialValue: T;
  initialErrors?: RecordErrors<T>;
  onValuesChange?: (value: T) => void;
  cancelLabel?: string;
  hideCancel?: boolean;
  fields: RecordField<T>[];
  validate?: (value: T) => RecordErrors<T>;
  onSubmit: (value: T) => void | Promise<void>;
  onCancel: () => void;
  onBusyChange?: (busy: boolean) => void;
  submitLabel?: string;
};

export type RecordManagerProps<T> = {
  filters?: RecordFilter<T>[];
  bulkActions?: BulkAction<T>[];
  renderDetail?: (record: T) => ReactNode;
  title: string;
  singularLabel: string;
  rows: T[];
  columns: TableColumn<T>[];
  fields: RecordField<T>[];
  rowId: (record: T) => string;
  recordLabel: (record: T) => string;
  createRecord: () => T;
  onRowsChange: (rows: T[]) => void;
  /** Return the server-confirmed record, including its stable ID. */
  onCreate: (draft: T) => T | Promise<T>;
  onUpdate: (draft: T, original: T) => T | Promise<T>;
  onDelete: (record: T) => void | Promise<void>;
  validate?: (draft: T, original: T | null) => RecordErrors<T>;
  loading?: boolean;
  error?: string;
  onRetry?: () => void;
  pageSize?: number;
};

export type FilterDefinition = {
